import bpy
for obj in bpy.context.scene.objects:
 if obj.type != 'MESH': continue
 evaluated = obj.evaluated_get(bpy.context.evaluated_depsgraph_get())
 mesh = evaluated.to_mesh(); mesh.calc_loop_triangles()
 if not obj.name.startswith('Component_'):
  print(obj.name,'vertices',len(mesh.vertices),'polygons',len(mesh.polygons),'triangles',len(mesh.loop_triangles))
  if len(mesh.loop_triangles) <= 4:
   for tri in mesh.loop_triangles:
    points=[evaluated.matrix_world @ mesh.vertices[index].co for index in tri.vertices]
    cross=(points[1]-points[0]).cross(points[2]-points[0])
    print('TRI',tri.index,'world',[tuple(point) for point in points],'area',cross.length/2,'normal',tuple(cross.normalized()))
 evaluated.to_mesh_clear()

